ROOT.scriptdef:
CREATE FUNCTION CDN.ECODNumerKorygowanego (@gidtyp integer,@gidfirma integer,@gidnumer integer,@krotkinumer tinyint)  
RETURNS varchar(30) AS  
BEGIN 
  DECLARE @numer integer;
  DECLARE @rok integer;
  DECLARE @miesiac integer
  DECLARE @seria varchar(10);
  DECLARE @sav_gidtyp integer;
  DECLARE @sav_gidnumer integer;
  SET @sav_gidtyp=0
  SET @sav_gidnumer=0
  WHILE @gidtyp=2041 AND (@sav_gidtyp<>@gidtyp OR @sav_gidnumer<>@gidnumer)
  BEGIN
    SET @sav_gidtyp=@gidtyp
    SET @sav_gidnumer=@gidnumer
    SELECT @gidnumer=B.TrN_GIDNumer,@gidtyp=B.TrN_GIDTyp,@numer=B.TrN_TrNNumer,@miesiac=B.TrN_TrNMiesiac,@rok=B.TrN_TrNRok,@seria=B.TrN_TrNSeria FROM CDN.TraNag AS A JOIN CDN.Tranag AS B ON B.TrN_GIDTyp=A.TrN_ZwRTyp AND B.TrN_GIDNumer=A.TrN_ZwRNumer AND A.TrN_GIDTyp=@gidtyp AND A.TrN_GIDnumer=@gidnumer
  END
  RETURN CDN.ECODPelnyNumerDokumentu(@gidtyp,@numer,@miesiac,@rok,@seria,@krotkinumer);
END
